def linear_count(items, target):
    count = 0
    for item in items:
        count += 1
        if item == target:
            break
    return count


def binary_count(items, target):
    low, high = 0, len(items) - 1
    count = 0
    while low <= high:
        mid = (low + high) // 2
        count += 1
        if items[mid] == target:
            break
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return count


